data = input()n = data.find("*")nminus = data.find("-")nplus = data.find("+")if n == -1:    if nminus > nplus and nminus != -1 and nplus != -1:  # 123+123-123        left = data[:nplus]        mid = data[nplus + 1: nminus]        right = data[nminus + 1:]        print(int(left) + int(mid) - int(right))    elif nplus > nminus and nminus != -1 and nplus != -1:  # 123-123+123        left = data[:nminus]        mid = data[nminus + 1: nplus]        right = data[nplus + 1:]        print(int(left) - int(mid) + int(right))    elif nplus != -1 and nminus == -1:  # 123+123+123        left = data[:nplus]        data = data[nplus + 1:]        nplus = data.find("+")        mid = data[:nplus]        right = data[nplus + 1:]        print(int(right) + int(mid) + int(left))    elif nminus != -1 and nplus == -1:  # 123-123-123        left = data[:nminus]        data = data[nminus + 1:]        nminus = data.find("-")        mid = data[:nminus]        right = data[nminus + 1:]        print(int(left) - int(mid) - int(right))elif n != -1 and nminus == -1 and nplus == -1:  # 123*123*123    left = data[:n]    data = data[n + 1:]    n = data.find("*")    mid = data[:n]    right = data[n + 1:]    print(int(left) * int(mid) * int(right))elif n != -1 and nminus == -1 and nplus != -1:  # 123+123*123 // 123*123+123    if n > nplus:  # 123+123*123        left = data[:nplus]        mid = data[nplus + 1:n]        right = data[n + 1:]        print(int(mid) * int(right) + int(left))    if n < nplus:  # 123*123+123        left = data[:n]        mid = data[n + 1:nplus]        right = data[nplus + 1:]        print(int(left) * int(mid) + int(right))elif n != 1 and nminus != -1 and nplus == -1:    if n > nminus:  # 123+123*123        left = data[:nminus]        mid = data[nminus + 1:n]        right = data[n + 1:]        print(int(left) - int(mid) * int(right))    if n < nminus:  # 123*123+123        left = data[:n]        mid = data[n + 1:nminus]        right = data[nminus + 1:]        print(int(left) * int(mid) - int(right))